function calcVal(xi, aryFunctionParameter, numFunction, count) {
  let val = 0;
  for (let j = 0; j < numFunction; j++) {
    val += sin(aryFunctionParameter[j][0] + 2 * PI * aryFunctionParameter[j][1] * aryFunctionParameter[j][2] * xi + aryFunctionParameter[j][3] * count)**aryFunctionParameter[j][4];
  }
  val /= numFunction; // -1 to 1

  return val;
}

class CurveLine {
  constructor(posY, id) {
    this.posY = posY;
    this.id = id;

    this.stepX = _minW / 200 / 1.5;// * random(1, 4);
    this.xiMin = -(int((_minW / 2) / this.stepX)) * 0.75;
    this.xiMax = -this.xiMin;

    this.ampY = _minW / 1.5 / 1.25 / 2;

    this.numFunction = 4;
    this.aryFunctionParameter = [];
    for (let i = 0; i < this.numFunction; i++) {
      this.aryFunctionParameter[i] = [
        random(2 * PI), //init
        random(0.5, 2), //freq
        random(0.001, 0.005) * random([-1, 1]) * 1, //stepSpeed
        random(0.005, 0.015) * 1.2, //timeSpeed
        int(random([1, 3, 5])) // order of function
      ];
    }

    let numBlock = int(random(1, 6)) * 2;
    this.numSeriesXi = int((this.xiMax - this.xiMin) / numBlock) + 0;//+2 to align edge
    this.aryChildren = [];

    let aryXi = [];
    let xi = 0;
    aryXi.unshift(xi); // xi=0
    xi--;
    let col;
    let col2;
    let _wG_5 = 0; while ((xi >= this.xiMin) && ++_wG_5 < 20000) { // minXi <= xi <= -1
      aryXi.unshift(xi);
      if (xi % this.numSeriesXi == 0) {
        col = color("#" + random(_palette));
        if (this.aryChildren.length > 0) {
          while (red(window.color(this.aryChildren[0].col)) == red(window.color(col)) && green(window.color(this.aryChildren[0].col)) == green(window.color(col)) && blue(window.color(this.aryChildren[0].col)) == blue(window.color(col))) {
            col = color("#" + random(_palette));
          }
        }
        col2 = color("#" + random(_palette));
        while (red(window.color(col)) == red(window.color(col2)) && green(window.color(col)) == green(window.color(col2)) && blue(window.color(col)) == blue(window.color(col2))) {
          col2 = color("#" + random(_palette));
        }
        this.aryChildren.unshift(new ChildCurveLine(aryXi, this.stepX, this.ampY, this.aryFunctionParameter, col, col2, this.id));
        aryXi = [];
        aryXi.unshift(xi);
      }
      xi--;
    }

    aryXi = [];
    xi = 0;
    aryXi.push(xi); // xi=0
    xi++;
    let _wG_6 = 0; while ((xi <= this.xiMax) && ++_wG_6 < 20000) { // 1 <= xi <= xiMax
      aryXi.push(xi);
      if (xi % this.numSeriesXi == 0) {
        col = color("#" + random(_palette));
        if (this.aryChildren.length > 0) {
          while (red(window.color(this.aryChildren[this.aryChildren.length-1].col)) == red(window.color(col)) && green(window.color(this.aryChildren[this.aryChildren.length-1].col)) == green(window.color(col)) && blue(window.color(this.aryChildren[this.aryChildren.length-1].col)) == blue(window.color(col))) {
            col = color("#" + random(_palette));
          }
        }
        col2 = color("#" + random(_palette));
        while (red(window.color(col)) == red(window.color(col2)) && green(window.color(col)) == green(window.color(col2)) && blue(window.color(col)) == blue(window.color(col2))) {
          col2 = color("#" + random(_palette));
        }
        this.aryChildren.push(new ChildCurveLine(aryXi, this.stepX, this.ampY, this.aryFunctionParameter, col, col2, this.id));
        aryXi = [];
        aryXi.push(xi);
      }
      xi++;
    }
  }

  draw() {
    push();
    translate(0, this.posY);
    for (let i = 0; i < this.aryChildren.length; i++) {
      this.aryChildren[i].draw();
    }
    pop();
  }
}

